function normalizeWhitespace(value) {
	return value.trim().split(/\s+/).filter(Boolean).join(" ");
}
function protectTechnicalSpans(value) {
	const protectedValues = [];
	let text = value;
	const protect = (span) => {
		const token = `__elizaProtected${protectedValues.length}__`;
		protectedValues.push(span);
		return token;
	};
	for (const pattern of PROTECTED_PATTERNS) text = text.replace(pattern, (...args) => {
		if (pattern.source.startsWith("(^|")) {
			const prefix = args[1] ?? "";
			const span = args[2] ?? "";
			return `${prefix}${protect(span)}`;
		}
		return protect(args[0] ?? "");
	});
	return {
		text,
		restore: (restoredText) => restoredText.replace(/__elizaProtected(\d+)__/g, (_match, index) => protectedValues[Number(index)] ?? "")
	};
}
function truncateDescription(value) {
	if (value.length <= MAX_DESCRIPTION_LENGTH) return value;
	const limit = MAX_DESCRIPTION_LENGTH - 3;
	const tokens = value.match(/\S+\s*/g) ?? [value];
	let out = "";
	for (const token of tokens) {
		const next = `${out}${token}`;
		if (next.trimEnd().length > limit) break;
		out = next;
	}
	return `${(out || value.slice(0, limit)).trimEnd().replace(/[\s,;:.!?-]+$/, "")}...`;
}
function compressPromptDescription(description) {
	if (typeof description !== "string" || !description.trim()) return "";
	const { text, restore } = protectTechnicalSpans(description);
	let compact = normalizeWhitespace(text).replace(/\*\*([^*]+)\*\*/g, "$1").replace(/\s+[-–—]\s+/g, " - ").replace(/[–—]/g, "-").replace(/\s*;\s*/g, ". ");
	for (const [pattern, replacement] of PHRASE_REPLACEMENTS) compact = compact.replace(pattern, replacement);
	for (const [pattern, replacement] of WORD_REPLACEMENTS) compact = compact.replace(pattern, replacement);
	compact = normalizeWhitespace(compact).replace(/\s+([,.;:!?])/g, "$1").replace(/([.!?]){2,}/g, "$1").replace(/\s*,\s*/g, ", ").replace(/\s*\.\s*/g, ". ").replace(/\(\s+/g, "(").replace(/\s+\)/g, ")").replace(/\s+\/\s+/g, "/").trim();
	for (const [pattern, replacement] of LEADING_VERB_REPLACEMENTS) compact = compact.replace(pattern, replacement);
	compact = restore(normalizeWhitespace(compact));
	return truncateDescription(compact);
}
