async function handlePreferenceReset(runtime2, message, callback) {
	const existingPrefs = await runtime2.getMemories({
		entityId: message.entityId,
		roomId: runtime2.agentId,
		tableName: USER_PREFS_TABLE,
		count: MAX_PREFS_PER_USER + 5
	});
	if (existingPrefs.length === 0) {
		await callback?.({
			text: "You don't have any custom interaction preferences set.",
			thought: "No preferences to reset"
		});
		return {
			text: "No preferences to reset",
			success: true,
			values: { resetCount: 0 },
			data: {
				action: "CHARACTER",
				op: "modify"
			}
		};
	}
	let deletedCount = 0;
	for (const pref of existingPrefs) if (pref.id) try {
		await runtime2.deleteMemory(pref.id);
		deletedCount++;
	} catch (err) {
		logger.warn({
			memoryId: pref.id,
			error: err.message
		}, "Failed to delete preference memory");
	}
	await callback?.({
		text: `I've cleared ${deletedCount} custom interaction preference(s). I'll go back to my default interaction style with you.`,
		thought: `Reset ${deletedCount} user preferences`,
		actions: ["CHARACTER"]
	});
	return {
		text: `Reset ${deletedCount} preferences`,
		success: true,
		values: { resetCount: deletedCount },
		data: {
			action: "CHARACTER",
			op: "modify"
		}
	};
}
